from sage.all_cmdline import *   # import sage library

_sage_const_2 = Integer(2); _sage_const_3 = Integer(3); _sage_const_4 = Integer(4); _sage_const_5 = Integer(5); _sage_const_0 = Integer(0); _sage_const_1 = Integer(1); _sage_const_2p0 = RealNumber('2.0')# anticommutator_of_hat_Z_and_hat_Y (1/4):
#   [hatZ^{(±)}_mu, hatZ^{(±)}_nu]_+ = 2M delta^M_{mu+nu,0} I   （複号同順）
#
# 独立経路:
#   左辺: hatZ_op を行列として作り、行列積で反交換子を直接評価
#   右辺: 2M delta^M I（閉じた表示）
# mu+nu が M の倍数になる場合とならない場合の両方を必ず含める。
import os
_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in dir() else '.'
load(os.path.join(_dir, '../../_shared/operators.sage'))

rep = CheckReport("anticommutator: [hatZ^{(±)}_mu, hatZ^{(±)}_nu]_+ = 2M δ^M_{μ+ν,0} I")

M_LIST = [_sage_const_2 , _sage_const_3 , _sage_const_4 , _sage_const_5 ]
n_deg = _sage_const_0 
n_nondeg = _sage_const_0 

for M in M_LIST:
    Mi = int(M)
    calM = [m for m in range(-Mi, Mi + _sage_const_1 ) if m != _sage_const_0 ]
    for sign in ['+', '-']:
        for mu in calM:
            for nu in calM:
                lhs = acomm(hatZ_op(mu, M, sign), hatZ_op(nu, M, sign))
                rhs = _sage_const_2p0  * float(Mi) * delta_M(mu + nu, _sage_const_0 , Mi) * eye_M(Mi)
                rep.close(lhs, rhs, "M=%d sign=%s mu=%+d nu=%+d" % (M, sign, mu, nu))
                if (mu + nu) % Mi == _sage_const_0 :
                    n_deg += _sage_const_1 
                else:
                    n_nondeg += _sage_const_1 

print("  μ+ν ≡ 0 (mod M) の組: %d 件、そうでない組: %d 件" % (n_deg, n_nondeg))
rep.truth(n_deg > _sage_const_0  and n_nondeg > _sage_const_0 , "両方の場合をカバーしている")

rep.finish()

